// WithDefaultAttributes returns a [metric.InstrumentOption] that specifies
// which attribute keys are allowed by default for a metric instrument.
//
// When the returned option is passed during instrument creation, only
// attributes whose keys appear in keys are included in recorded data points.
// Recorded attributes with keys not in keys are dropped.
//
// Passing no keys results in all attributes being filtered out (an empty
// attribute set is recorded).
//
// If an explicitly matching [go.opentelemetry.io/otel/sdk/metric.View] is
// defined for the instrument, the view's attribute configuration takes
// precedence and the filtering configured here is not applied.
func WithDefaultAttributes(keys ...attribute.Key) metric.InstrumentOption {
	// Ensure the allowed keys are non-nil even when no keys are provided so a
	// deny-all (empty allow-list) filter is applied instead of being treated
	// as "no filtering configured".
	if keys == nil {
		keys = []attribute.Key{}
	}
	return defaultAttributesOption{keys: keys}
}

// defaultAttributesOption is a [metric.InstrumentOption] that carries the set
// of attribute keys allowed by default for an instrument.
type defaultAttributesOption struct {
	keys []attribute.Key
}

// Experimental marks the option as experimental. It also ensures the option is
// ignored by the standard metric API configuration (which skips experimental
// options), preventing panics when used with the standard API.
func (defaultAttributesOption) Experimental() {}

// AllowedKeys returns the attribute keys allowed by default for the
// instrument.
func (o defaultAttributesOption) AllowedKeys() []attribute.Key { return o.keys }

