func collectSumAttrs(t *testing.T, r *ManualReader) []attribute.Set {
	var rm metricdata.ResourceMetrics
	if err := r.Collect(context.Background(), &rm); err != nil {
		t.Fatal(err)
	}
	var out []attribute.Set
	for _, sm := range rm.ScopeMetrics {
		for _, m := range sm.Metrics {
			sum := m.Data.(metricdata.Sum[int64])
			for _, dp := range sum.DataPoints {
				out = append(out, dp.Attributes)
			}
		}
	}
	return out
}

func TestScratchDefaultAttributes(t *testing.T) {
	kFoo, kBar := attribute.Key("foo"), attribute.Key("bar")
	attrs := metric.WithAttributes(kFoo.String("1"), kBar.String("2"))

	// subset filtering
	r := NewManualReader()
	mp := NewMeterProvider(WithReader(r))
	c, _ := mp.Meter("s").Int64Counter("c", withDefaultAttrs(kFoo))
	c.Add(context.Background(), 1, attrs)
	got := collectSumAttrs(t, r)
	if len(got) != 1 || got[0].Len() != 1 {
		t.Fatalf("subset: want 1 attr, got %v", got)
	}
	if v, ok := got[0].Value(kFoo); !ok || v.AsString() != "1" {
		t.Fatalf("subset: want foo=1, got %v", got[0].Encoded(attribute.DefaultEncoder()))
